export const hamletPartials = {
  "hamlet.defaultmarkups": "{{!-- Clean all inclusions of all widgets automatically  --}}\n{{#each defaultmarkups}}\n<b:defaultmarkup type='{{@key}}'>\n  {{#each this}}\n  <b:includable id='{{this}}'/>\n  {{/each}}\n</b:defaultmarkup>\n{{/each}}\n",
  "hamlet.snippet": "{{!--\nCreates a clean text snippet of a string with conditional ellipsis support.\n@author zkreations\n@param {String} [text=\"\"] - Text or HTML content to be shortened\n@param {String} [tag=\"p\"] - Container HTML tag name\n@param {String} [id] - Container HTML id\n@param {String} [class] - Container CSS class\n@param {Number} [limit=70] - Maximum length of the string\n@param {String} [ellipsis=\"...\"] - Ellipsis to be added only if the text is truncated\n--}}\n<b:includable id='@snippet'>\n  <b:with value='data:text ? (data:text snippet {\n    links: false,\n    ellipsis: false,\n    linebreaks: false\n  }) : \"\"' var='cleanString'>\n    <b:if cond='data:cleanString != \"\"'>\n      <b:with value='(data:limit + 0) == data:limit ? (data:limit * 1) : 70' var='maxLength'>\n        <b:tag expr:name='data:tag ?: \"p\"'>\n          <b:class cond='data:class' expr:name='data:class'/>\n          <b:attr name='id' expr:value='data:id'/>\n          <b:with value='data:cleanString snippet {\n            length: data:maxLength,\n            links: false,\n            ellipsis: false,\n            linebreaks: false\n          }' var='truncatedText'>\n            <b:eval expr='data:truncatedText + (\n              data:cleanString.size > data:maxLength ? (data:ellipsis ?: \"...\") : \"\"\n            )'/>\n          </b:with>\n        </b:tag>\n      </b:with>\n    <b:else/>\n      <b:comment render='true'>No visible text to display after sanitization.</b:comment>\n    </b:if>\n  </b:with>\n</b:includable>\n",
  "hamlet.picture": "{{!--\nCreate a responsive custom picture tag using native Blogger image sizing.\n@author zkreations\n@param {image} src - Image URL or Blogger image object\n@param {number[]} [sourceSet=[700,400]] - Array of widths for the responsive sources\n@param {Number} [width] - Explicit image width for the fallback img\n@param {Number} [height] - Explicit image height for the fallback img\n@param {String} [ratio] - Aspect ratio (e.g., \"16:9\", \"1:1\")\n@param {String} [id] - Unique identifier for the img tag\n@param {String} [class] - Additional CSS classes for the img tag\n@param {String} [imgClass] - CSS classes for the fallback img tag\n@param {string} [sizes] - Sizes attribute\n@param {string} [loading] - Loading attribute\n@param {string} [fetchpriority] - Fetch priority attribute\n@param {string} [crossorigin] - Cross-origin attribute\n@param {string} [decoding] - Decoding attribute\n@param {string} [referrerpolicy] - Referrer policy attribute\n@param {string} [alt] - Alt text\n@param {string} [params] - Additional parameters for proxy images\n--}}\n<b:includable id='@picture'>\n  <b:if cond='data:src'>\n    <picture>\n      <b:class cond='data:class' expr:name='data:class'/>\n      <b:with value='data:src.isYoutube\n        ? data:src.youtubeMaxResDefaultUrl\n        : data:src' var='baseImage'>\n        <b:with value='data:sourceSet ?: [700, 400]' var='availableSizes'>\n          <b:with value='[\n            \"com/img/a/\",\n            \"com/blogger_img_proxy\"\n          ] any (server => server in data:baseImage)' var='isProxyImg'>\n            <b:with value='data:params and data:isProxyImg ? (\"-\" + data:params) : \"\"' var='params'>\n              <b:loop index='i' values='data:availableSizes' var='size'>\n                <b:if cond='data:i + 1 != data:availableSizes.length'>\n                  <b:with value='resizeImage(data:baseImage, data:size, data:ratio)' var='sourceUrl'>\n                    <source expr:media='\"(min-width: \" + data:size + \"px)\"' expr:srcset='data:sourceUrl + data:params'/>\n                  </b:with>\n                </b:if>\n              </b:loop>\n              <b:with value='data:availableSizes.last ?: 600' var='fallbackSize'>\n                <b:with value='resizeImage(data:baseImage, data:fallbackSize, data:ratio)' var='fallbackUrl'>\n                  <b:tag name='img'>\n                    <b:attr name='b:whitespace' value='remove'/>\n                    <b:class cond='data:imgClass' expr:name='data:imgClass'/>\n                    <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\n                      <b:with expr:value='+(\"data:\",data:attr)' var='value'>\n                        <b:attr expr:name='data:attr' expr:value='data:value'/>\n                      </b:with>\n                    </b:loop>\n                    <b:attr name='width' expr:value='data:width ?: data:fallbackUrl.width'/>\n                    <b:attr name='height' expr:value='data:height ?: data:fallbackUrl.height'/>\n                    <b:attr name='src' expr:value='data:fallbackUrl + data:params'/>\n                  </b:tag>\n                </b:with>\n              </b:with>\n            </b:with>\n          </b:with>\n        </b:with>\n      </b:with>\n    </picture>\n  <b:else/>\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\n  </b:if>\n</b:includable>\n",
  "hamlet.meta": "{{!--\nGenerates essential metadata, SEO, and Open Graph/Twitter Cards.\n@author zkreations\n@param {String} [icon] - Base URL to generate responsive favicons.\n@param {Array[Number]} [iconSizes=[32,96,180,192]] - Dimensions for the favicons.\n@param {String} [robots] - Custom meta robots configuration for homepage/posts.\n@param {String} [defaultImage] - Default image URL for social networks.\n@param {String} [twitterCard=\"summary_large_image\"] - Twitter Card type (summary, summary_large_image).\n@param {String} [twitterSite] - Twitter/X handle of the website (e.g., @zkreations).\n--}}\n<b:includable id='@meta'>\n  <meta expr:charset='data:blog.encoding'/>\n  <meta content='width=device-width,initial-scale=1' name='viewport'/>\n  <b:if cond='data:icon'>\n    <b:loop values='data:iconSizes ?: [32,96,180,192]' var='size'>\n      <link expr:href='resizeImage(data:icon, data:size, \"1:1\")' rel='icon' expr:sizes='data:size + \"x\" + data:size' type='image/png'/>\n    </b:loop>\n  <b:else/>\n    <link expr:href='data:blog.blogspotFaviconUrl' rel='icon' type='image/x-icon'/>\n  </b:if>\n  <b:if cond='data:view.description'>\n    <meta expr:content='data:view.description.escaped' name='description'/>\n    <meta expr:content='data:view.description.escaped' property='og:description'/>\n    <meta expr:content='data:view.description.escaped' name='twitter:description'/>\n  </b:if>\n  <link expr:href='data:view.url.canonical' rel='canonical'/>\n  <meta expr:content='data:view.url.canonical' property='og:url'/>\n  <meta expr:content='data:view.url.canonical' name='twitter:url'/>\n  <meta expr:content='data:view.title.escaped' property='og:title'/>\n  <meta expr:content='data:view.isHomepage or data:view.isSingleItem\n    ? (data:robots ?: \"index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1\")\n    : \"noindex,follow\"' name='robots'/>\n  <meta expr:content='data:view.isSingleItem ? \"article\" : \"website\"' property='og:type'/>\n  <b:with value='data:view.featuredImage ? data:view.featuredImage : (data:defaultImage ? data:defaultImage : false)' var='rawImage'>\n    <b:if cond='data:rawImage'>\n      <b:if cond='data:rawImage.isResizable'>\n        <meta expr:content='resizeImage(data:rawImage, 1200, \"1200:630\")' property='og:image'/>\n        <meta expr:content='resizeImage(data:rawImage, 1200, \"1200:630\")' name='twitter:image'/>\n        <meta content='1200' property='og:image:width'/>\n        <meta content='630' property='og:image:height'/>\n      <b:else/>\n        <meta expr:content='data:rawImage' property='og:image'/>\n        <meta expr:content='data:rawImage' name='twitter:image'/>\n      </b:if>\n    </b:if>\n  </b:with>\n  <meta expr:content='data:twitterCard ?: \"summary_large_image\"' name='twitter:card'/>\n  <b:if cond='data:twitterSite'>\n    <meta expr:content='data:twitterSite' name='twitter:site'/>\n  </b:if>\n</b:includable>\n",
  "hamlet.menu": "{{!--\nCreate a menu from a list of links\n@author zkreations\n@param {array} links - Array of links\n@param {string} [prefix=\"__\"] - Prefix for filter links\n@param {string} [id] - Id for the menu\n@param {string} [class] - Class for the menu\n@param {String} [itemClass] - Base class for the items (li)\n@param {String} [subnavClass] - Class for the nested submenus (ul)\n@param {String} [linkClass] - Base class for the anchors (a)\n@param {String} [hereClass] - State class when the link matches the current URL\n@param {String} [externalClass] - State class for external references\n--}}\n<b:includable id='@menu'>\n  <b:with value='data:prefix ?: \"__\"' var='prefix'>\n    <b:if cond='!data:links.any'>\n      <b:comment render='true'>The array can't be empty</b:comment>\n    <b:elseif cond='data:links[0].title contains data:prefix'/>\n      <b:comment render='true'>The first element can't have the prefix</b:comment>\n    <b:elseif cond='data:links any (l => l.title + 0 == l.title)'/>\n      <b:comment render='true'>The element can't be a number</b:comment>\n    <b:else/>\n      <ul class='nav'>\n        <b:class cond='data:class' expr:name='data:class'/>\n        <b:attr name='id' expr:value='data:id'/>\n        <b:loop index='i' values='data:links' var='link'>\n          <b:with value='{\n            current: (data:link.title contains data:prefix),\n            next: (data:links[data:i + 1].title contains data:prefix)\n          }' var='state'>\n            <b:with value='{\n              start: (data:state.next and !data:state.current),\n              end: (!data:state.next and data:state.current)\n            }' var='menu'>\n              <b:eval expr='\"&lt;li class=\\\"nav-item \" + (data:menu.start ? \"has-subnav \" : \"\") + data:itemClass + \"\\\">\"'/>\n              <a class='nav-link' expr:href='data:link.href'>\n                <b:class cond='data:linkClass' expr:name='data:linkClass'/>\n                <b:if cond='data:link.isCurrentPage or data:view.url.canonical == data:link.href'>\n                  <b:class name='is-here'/>\n                  <b:class cond='data:hereClass' expr:name='data:hereClass'/>\n                </b:if>\n                <b:if cond='data:link.href contains \"?ref=\"'>\n                  <b:class name='is-external'/>\n                  <b:class cond='data:externalClass' expr:name='data:externalClass'/>\n                  <b:attr name='target' value='_blank'/>\n                  <b:attr name='rel' value='noopener noreferrer'/>\n                </b:if>\n                <data:link.title/>\n              </a>\n              <b:eval expr='data:menu.end ? \"&lt;/li>&lt;/ul>\" : \"\"'/>\n              <b:eval expr='data:menu.start ? \"&lt;ul class=\\\"nav-subnav \" + data:subnavClass + \" \\\">\" : \"&lt;/li>\"'/>\n            </b:with>\n          </b:with>\n        </b:loop>\n      </ul>\n    </b:if>\n  </b:with>\n</b:includable>\n",
  "hamlet.kind": "{{!--\nadd classes to body tag based on the current view\n@author zkreations\n@param {boolean} [viewId=true] - Add class based on ID (e.g. postId, pageId)\n--}}\n<b:includable id='@kind'>\n  <b:class cond='data:view.isHomepage' name='is-home'/>\n  <b:class cond='data:view.isMultipleItems' name='is-items'/>\n  <b:class cond='data:view.isPost' name='is-post'/>\n  <b:class cond='data:view.isPage' name='is-page'/>\n  <b:class cond='data:view.isArchive' name='is-archive'/>\n  <b:class cond='data:view.isLabelSearch' name='is-label'/>\n  <b:class cond='data:view.isSearch' name='is-search'/>\n  <b:class cond='data:view.isError' name='is-error'/>\n  <b:class cond='data:view.isPreview' name='is-preview'/>\n  <b:if cond='data:view.isSingleItem'>\n    <b:class name='is-single'/>\n    <b:class cond='data:viewId != false' expr:name='\"single-id-\" + (data:view.postId ?: data:view.pageId)'/>\n  </b:if>\n</b:includable>\n",
  "hamlet.image": "{{!--\nCreate an image tag with optional attributes and responsive support\n@author zkreations\n@param {image} src - Image URL\n@param {number[]} [sourceSet] - Array of image widths (e.g. [320, 640, 1024])\n@param {number} [width] - Image width\n@param {number} [height] - Image height\n@param {number} [resize] - Change dimensions\n@param {string} [ratio] - Aspect ratio\n@param {string} [id] - Image ID\n@param {string} [class] - Additional classes\n@param {string} [sizes] - Sizes attribute\n@param {string} [loading] - Loading attribute\n@param {string} [fetchpriority] - Fetch priority attribute\n@param {string} [crossorigin] - Cross-origin attribute\n@param {string} [decoding] - Decoding attribute\n@param {string} [referrerpolicy] - Referrer policy attribute\n@param {string} [alt] - Alt text\n@param {string} [params] - Additional parameters for proxy images\n--}}\n<b:includable id='@image'>\n  <b:if cond='data:src'>\n    <b:with value='data:src.isYoutube\n      ? data:src.youtubeMaxResDefaultUrl\n      : data:src' var='baseImage'>\n      <b:with value='(data:resize\n        ? resizeImage(data:baseImage, data:resize, data:ratio)\n        : data:baseImage\n      )' var='image'>\n        <b:tag name='img'>\n          <b:attr name='b:whitespace' value='remove'/>\n          <b:class cond='data:class' expr:name='data:class'/>\n          <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\n            <b:with expr:value='+(\"data:\",data:attr)' var='value'>\n              <b:attr expr:name='data:attr' expr:value='data:value'/>\n            </b:with>\n          </b:loop>\n          <b:with value='[\n            \"com/img/a/\",\n            \"com/blogger_img_proxy\"\n          ] any (server => server in data:image)' var='isProxyImg'>\n            <b:with value='data:params and data:isProxyImg ? (\"-\" + data:params) : \"\"' var='params'>\n              <b:with value='data:sourceSet ? resizeImage(data:image, data:sourceSet.first, data:ratio) : data:image' var='image'>\n                <b:attr name='src' expr:value='data:image + data:params'/>\n                <b:attr name='width' expr:value='data:width ?: data:image.width'/>\n                <b:attr name='height' expr:value='data:height ?: data:image.height'/>\n              </b:with>\n            </b:with>\n          </b:with>\n          <b:if cond='data:sourceSet'>\n            <b:attr name='srcset' expr:value='sourceSet(data:image, data:sourceSet, data:ratio)'/>\n          </b:if>\n        </b:tag>\n      </b:with>\n    </b:with>\n  <b:else/>\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\n  </b:if>\n</b:includable>\n",
  "hamlet.contrast": "{{!--\nEvaluates a color's brightness and exposes its contrast state.\n@author zkreations\n@param {Color} color - Color variable from data:skin.vars\n@param {Number} [threshold=155] - Brightness limit to trigger the dark state (0-255)\n@param {String} [attr=\"data-theme\"] - Target attribute name to render\n--}}\n<b:includable id='@contrast'>\n  <b:with value='+((data:color.red * 0.299), (data:color.green * 0.587), (data:color.blue * 0.114))' var='brightness'>\n    <b:with value='(data:threshold + 0) == data:threshold ? (data:threshold * 1) : 155' var='limit'>\n      <b:attr expr:name='data:attr ?: \"data-theme\"' expr:value='data:brightness lt data:limit\n        ? \"dark\"\n        : \"light\"'/>\n    </b:with>\n  </b:with>\n</b:includable>\n",
  "hamlet.avatar": "{{!--\nCreate an avatar image with optional default image\n@author zkreations\n@param {image} src - Image URL\n@param {image} [default] - Default image URL\n@param {number} [width] - Image width\n@param {number} [height] - Image height\n@param {number} [resize=40] - Change dimensions\n@param {string} [id] - Image ID\n@param {string} [class] - Additional classes\n@param {string} [sizes] - Sizes attribute\n@param {string} [loading] - Loading attribute\n@param {string} [fetchpriority] - Fetch priority attribute\n@param {string} [crossorigin] - Cross-origin attribute\n@param {string} [decoding] - Decoding attribute\n@param {string} [referrerpolicy] - Referrer policy attribute\n@param {string} [alt] - Alt text\n--}}\n<b:includable id='@avatar'>\n  <b:if cond='data:src'>\n    <b:with value='data:default ?: \"https://lh3.googleusercontent.com/a/default-user\"' var='default'>\n      <b:with value='resizeImage((data:src contains \"/img/bl\" ? data:default : data:src), (data:resize ?: 40), \"1:1\")' var='image'>\n        <b:tag name='img'>\n          <b:attr name='b:whitespace' value='remove'/>\n          <b:class cond='data:class' expr:name='data:class'/>\n          <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\n            <b:with expr:value='+(\"data:\",data:attr)' var='value'>\n              <b:attr expr:name='data:attr' expr:value='data:value'/>\n            </b:with>\n          </b:loop>\n          <b:attr name='src' expr:value='data:image'/>\n          <b:attr name='width' expr:value='data:image.width'/>\n          <b:attr name='height' expr:value='data:image.height'/>\n        </b:tag>\n      </b:with>\n    </b:with>\n  <b:else/>\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\n  </b:if>\n</b:includable>\n",
  "hamlet.attr": "{{!--\nAdd or remove multiple attributes\n@author zkreations\n@param {Array[Array]} data - Array of attribute name-value pairs\n--}}\n<b:includable id='@attr'>\n  <b:if cond='data:'>\n    <b:loop values='data:' var='i'>\n      <b:attr expr:name='data:i[0]' expr:value='data:i[1]'/>\n    </b:loop>\n  <b:else/>\n    <b:comment render='true'>Parameter [data] is required.</b:comment>\n  </b:if>\n</b:includable>\n",
  "hamlet.adsense": "{{!--\nAdSense async script\n@author zkreations\n--}}\n<b:includable id='@adsense'>\n  <b:if cond='data:blog.adsenseHostId and not data:blog.adsenseAutoAds'>\n    <b:tag async='async' name='script' cond='data:blog.adsenseClientId and data:blog.adsenseHasAds' expr:src='\"//pagead2.googlesyndication.com/pagead/js/adsbygoogle.js\" params {client: data:blog.adsenseClientId}' crossorigin='anonymous'/>\n  </b:if>\n</b:includable>\n",
  "hamlet.ads": "{{!--\nCreate adsense ads\n@author zkreations\n@param {string} [adClientId=data:blog.adsenseClientId] - Adsense client ID\n@param {string} [style=\"display: block\"] - Inline style\n@param {string} [slot] - ID of ad slot created in Adsense\n@param {string} [layout] - ID of layout (in-feed & in-article ads)\n--}}\n<b:includable id='@ads'>\n  <b:tag class='adsbygoogle' name='ins' data-full-width-responsive='true'>\n    <b:attr name='data-ad-client' expr:value='data:adClientId ?: data:blog.adsenseClientId'/>\n    <b:attr name='data-ad-host' expr:value='data:blog.adsenseHostId'/>\n    <b:attr name='data-ad-slot' expr:value='data:slot'/>\n    <b:attr name='data-ad-format' expr:value='data:layout ? \"fluid\" : \"auto\"'/>\n    <b:attr expr:name='\"data-ad-layout\" + (data:layout != \"in-article\" ? \"-key\" : \"\")' expr:value='data:layout'/>\n    <b:attr name='style' expr:value='data:style ?: \"display: block\"'/>\n  </b:tag>\n  <script>(adsbygoogle = window.adsbygoogle || []).push({})</script>\n</b:includable>\n",
  "hamlet.overrides": "{{> hamlet.defaultmarkups}}\n",
  "hamlet.functions": "{{> hamlet.adsense}}\n{{> hamlet.ads}}\n{{> hamlet.attr}}\n{{> hamlet.avatar}}\n{{> hamlet.contrast}}\n{{> hamlet.image}}\n{{> hamlet.kind}}\n{{> hamlet.menu}}\n{{> hamlet.meta}}\n{{> hamlet.picture}}\n{{> hamlet.snippet}}\n"
}
